import sys
from itertools import product
from math import factorial
MOD = 998244353
data = sys.stdin.read().split()
n = int(data[0])
c = [int(v) for v in data[1:1 + n]]
if n <= 7:
    count = 0
    for targets in product(range(1, n + 1), repeat=n):
        if any(t == i for i, t in enumerate(targets, start=1)):
            continue
        if all(targets.count(j) == c[j - 1] for j in range(1, n + 1)):
            count += 1
    print(count % MOD)
else:
    # exact integers, no modular arithmetic: inclusion-exclusion over the self-voting seats
    if sum(c) != n:
        print(0)
    else:
        poly = [1]
        for cj in c:
            nxt = poly + [0]
            for k in range(len(poly)):
                nxt[k + 1] += poly[k] * cj
            poly = nxt
        total = sum((-1) ** k * factorial(n - k) * poly[k] for k in range(n + 1))
        denom = 1
        for cj in c:
            denom *= factorial(cj)
        assert total % denom == 0
        print((total // denom) % MOD)
